using System;using Orbit;
class RadminRulesTests {
 static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+(++n)+" "+name);}static void Fails(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception(name+" accepted");}
 static void Main(){Check(RadminRules.Network("  Наш мир  ")=="Наш мир","network name trimmed");Fails(()=>RadminRules.Network("\r\n"),"empty network rejected");Fails(()=>RadminRules.Network("name\nother"),"network controls rejected");Fails(()=>RadminRules.Password("secret\nsecond"),"password controls rejected");Check(RadminRules.Password("пароль 123")!="","Unicode password accepted");Check(RadminRules.JoinButton("Join network…")&&RadminRules.JoinButton("Присоединиться к сети"),"known join controls supported");Check(!RadminRules.JoinButton("Delete network")&&!RadminRules.JoinButton("Join public network"),"unrelated controls rejected");Check(RadminRules.SubmitButton("Присоединиться")&&!RadminRules.SubmitButton("Create"),"only join is submitted");Check(RadminRules.MainWindow("Radmin VPN")&&!RadminRules.MainWindow("Radmin VPN settings"),"only exact main window");Check(RadminRules.NetworkItem("Our world","Our world")&&!RadminRules.NetworkItem("Our world 2","Our world")&&!RadminRules.NetworkItem("our world","Our world"),"exact membership only");RadminRules.Validate(new RadminSettings{network="group",autoStart=true});Fails(()=>RadminRules.Validate(new RadminSettings{autoStart=true}),"autostart needs a named network");Console.WriteLine("Radmin rules: "+n+" passed");}
}
